#!/usr/bin/env node
/**
 * Sync AI-gateway HTTP message catalogs into the unified localization catalog
 * storage (src/services/localization/catalogs/gateway).
 *
 * Reads every src/ai-gateway/i18n/messages/<locale>.json and emits one
 * auto-generated TypeScript seed module per locale plus a wiring index, so the
 * gateway strings become seed data owned by the unified localization system.
 *
 * Usage:
 *   node scripts/sync-gateway-i18n-catalogs.mjs
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const MESSAGES_DIR = path.join(ROOT, 'src', 'ai-gateway', 'i18n', 'messages');
const OUTPUT_DIR = path.join(ROOT, 'src', 'services', 'localization', 'catalogs', 'gateway');

const HEADER = [
  '/* eslint-disable */',
  '// AUTO-GENERATED by scripts/sync-gateway-i18n-catalogs.mjs - do not edit by hand.',
].join('\n');

/** Mirrors SupportedLocale from src/services/localization/localeContracts.ts. */
const SUPPORTED_LOCALES = new Set([
  'en', 'pt', 'es', 'zh', 'zh-hant', 'ja', 'de', 'fr',
  'ru', 'ko', 'it', 'ar', 'tr', 'uk', 'af', 'ga', 'hu',
]);

function listGatewayLocaleFiles() {
  return fs
    .readdirSync(MESSAGES_DIR)
    .filter((name) => name.endsWith('.json'))
    .sort();
}

function toModuleTag(localeTag) {
  return localeTag.toLowerCase();
}

function toIdentifier(tag) {
  return `gateway_${tag.replace(/[^a-z0-9]/g, '_')}`;
}

/**
 * Decides where a gateway seed mounts inside the localization service:
 * - Plain tags whose base language is a builtin SupportedLocale extend that
 *   builtin catalog (for example "de" layers onto the de catalog).
 * - Regional tags extend their base language only when no sibling plain-tag
 *   seed exists ("zh-CN" extends zh, "uk-UA" extends uk), otherwise they
 *   register under their own exact normalized tag ("pt-br" keeps pt intact).
 */
function resolveMountTarget(tag, availableTags) {
  if (!tag.includes('-') && SUPPORTED_LOCALES.has(tag)) {
    return { kind: 'extension', locale: tag };
  }
  const base = tag.split('-')[0];
  if (SUPPORTED_LOCALES.has(base) && !availableTags.has(base)) {
    return { kind: 'extension', locale: base };
  }
  return { kind: 'dynamic', locale: tag };
}

function serializeSeedModule(tag, identifier, catalog) {
  return `${HEADER}
import type { GatewayCatalogSection } from '../../localeContracts.js';

export const ${identifier}: GatewayCatalogSection = ${JSON.stringify(catalog, null, 2)};
`;
}

function serializeIndexModule(modules, mountTargets) {
  const imports = modules
    .map(({ tag, identifier }) => `import { ${identifier} } from './${tag}.js';`)
    .join('\n');

  const seedEntries = modules
    .map(({ tag, identifier }) => `  '${tag}': ${identifier},`)
    .join('\n');

  const extensionEntries = modules
    .filter(({ tag }) => mountTargets.get(tag).kind === 'extension')
    .map(({ tag, identifier }) => `  '${mountTargets.get(tag).locale}': { gateway: ${identifier} },`)
    .join('\n');

  const dynamicTags = modules
    .filter(({ tag }) => mountTargets.get(tag).kind === 'dynamic')
    .map(({ tag }) => `  '${tag}',`)
    .join('\n');

  return `${HEADER}
import type { GatewayCatalogSection, SupportedLocale } from '../../localeContracts.js';
${imports}

export interface GatewayCatalogExtension {
  gateway?: GatewayCatalogSection;
}

/** Every synced gateway seed keyed by its normalized locale tag. */
export const GATEWAY_SEED_CATALOGS: Record<string, GatewayCatalogSection> = {
${seedEntries}
};

/** Gateway sections layered onto builtin locale catalogs (base-language match). */
export const GATEWAY_CATALOG_EXTENSIONS: Partial<Record<SupportedLocale, GatewayCatalogExtension>> = {
${extensionEntries}
};

/**
 * Locale tags carried solely by gateway seeds or by regional variants that
 * must not shadow their base builtin catalog; resolved under exact tags.
 */
export const GATEWAY_DYNAMIC_CATALOG_TAGS: readonly string[] = [
${dynamicTags}
];
`;
}

function main() {
  const files = listGatewayLocaleFiles();
  if (files.length === 0) {
    console.error(`No gateway message catalogs found under ${MESSAGES_DIR}`);
    process.exit(1);
  }

  fs.mkdirSync(OUTPUT_DIR, { recursive: true });

  const modules = [];
  for (const file of files) {
    const localeTag = file.replace(/\.json$/, '');
    const tag = toModuleTag(localeTag);
    const identifier = toIdentifier(tag);
    const raw = fs.readFileSync(path.join(MESSAGES_DIR, file), 'utf8');
    const catalog = JSON.parse(raw);
    const moduleSource = serializeSeedModule(tag, identifier, catalog);
    fs.writeFileSync(path.join(OUTPUT_DIR, `${tag}.ts`), moduleSource, 'utf8');
    modules.push({ tag, identifier });
    console.log(`seeded ${tag} (${(moduleSource.length / 1024).toFixed(1)} KB)`);
  }

  const availableTags = new Set(modules.map((module) => module.tag));
  const mountTargets = new Map();
  for (const module of modules) {
    mountTargets.set(module.tag, resolveMountTarget(module.tag, availableTags));
  }

  fs.writeFileSync(
    path.join(OUTPUT_DIR, 'index.ts'),
    serializeIndexModule(modules, mountTargets),
    'utf8',
  );

  const extensions = [...mountTargets.entries()].filter(([, target]) => target.kind === 'extension');
  const dynamics = [...mountTargets.entries()].filter(([, target]) => target.kind === 'dynamic');
  console.log(`\nSynced ${modules.length} gateway catalogs into ${path.relative(ROOT, OUTPUT_DIR)}`);
  console.log(`  extensions onto builtin catalogs: ${extensions.map(([tag, target]) => `${tag}→${target.locale}`).join(', ')}`);
  console.log(`  dynamic exact-tag registrations: ${dynamics.map(([tag]) => tag).join(', ')}`);
}

main();
